import { cn } from "@/lib/dooping/utils";
import {
  type BarDatum,
  type ValueFmt,
  PALETTE,
  capItems,
  defaultFmt,
  ChartDataTable,
  ChartEmpty,
} from "@/components/dooping/base";

export interface BarChartProps {
  data: BarDatum[];
  /** 這張圖在講什麼——同時是 aria-label 摘要與資料表 caption 的開頭。 */
  title?: string;
  /**
   * 在長條頂端標數值。**列印與觸控裝置一定要開**——
   * 沒有 hover 的情境裡，不標值的長條只是形狀。
   */
  showValues?: boolean;
  /** 類別上限（含彙總項），超過取值最大的前幾名、其餘併成「其他」。 */
  maxItems?: number;
  valueFmt?: ValueFmt;
  /** 點擊鑽取。明細清單由宿主渲染——元件不猜「鑽下去看什麼」。 */
  onSelect?: (index: number, datum: BarDatum) => void;
  selectedIndex?: number;
  /** 單一序列色。預設 `PALETTE[0]`——它是全站單序列圖的預設色，要穩定。 */
  color?: string;
  height?: number;
  className?: string;
}

/**
 * 長條圖：比較同一個量在不同類別間的大小。
 * 類別是時間（月份、週）請用 TrendChart——長條不表達「順序連續」。
 */
export function BarChart({
  data,
  title = "長條圖",
  showValues = false,
  maxItems = 12,
  valueFmt = defaultFmt,
  onSelect,
  selectedIndex,
  color = PALETTE[0],
  height = 180,
  className,
}: BarChartProps) {
  if (data.length === 0) return <ChartEmpty />;
  const items = capItems(data, maxItems);
  // 全零時以 1 為底避免除以零——座標軸正常、長度全部是 0。
  // 「本期皆為 0」要由宿主明說，否則使用者會以為資料沒載入。
  const max = Math.max(1, ...items.map((d) => d.value));

  const slot = 56;
  const pad = { top: showValues ? 18 : 8, bottom: 20 };
  const plotH = height - pad.top - pad.bottom;
  const W = items.length * slot;
  const peak = items.reduce((a, b) => (b.value > a.value ? b : a), items[0]);

  return (
    <div className={cn("overflow-x-auto", className)}>
      <svg
        role="img"
        aria-label={`${title}，共 ${items.length} 項，最高為 ${peak.label} ${valueFmt(peak.value)}`}
        viewBox={`0 0 ${W} ${height}`}
        width={W}
        height={height}
        className="block"
      >
        {/* 基準線：只畫底線，不做完整刻度系統（閱讀型圖表的刻意限制） */}
        <line x1={0} y1={height - pad.bottom} x2={W} y2={height - pad.bottom} stroke="var(--chart-axis)" />
        {items.map((d, i) => {
          const h = (d.value / max) * plotH;
          const x = i * slot + 10;
          const y = height - pad.bottom - h;
          const dim = selectedIndex != null && selectedIndex !== i;
          return (
            <g
              key={d.id ?? d.label}
              onClick={onSelect ? () => onSelect(i, d) : undefined}
              className={cn(onSelect && "cursor-pointer")}
            >
              {/* 原生 <title> 是零相依的 hover 提示；鍵盤與報讀器走下方資料表 */}
              <title>{`${d.label}：${valueFmt(d.value)}`}</title>
              <rect x={x} y={y} width={slot - 20} height={h} fill={color} opacity={dim ? 0.35 : 1} />
              {showValues && (
                <text x={x + (slot - 20) / 2} y={y - 4} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
                  {valueFmt(d.value)}
                </text>
              )}
              <text x={x + (slot - 20) / 2} y={height - 6} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
                {d.label}
              </text>
            </g>
          );
        })}
      </svg>
      <ChartDataTable
        caption={`${title}（資料表）`}
        head={["項目", "數值"]}
        rows={items.map((d) => [d.label, valueFmt(d.value)])}
        onSelect={onSelect ? (i) => onSelect(i, items[i]) : undefined}
        selectedIndex={selectedIndex}
      />
    </div>
  );
}

import type { ReactNode } from "react";
import { cn, formatNumber } from "@/lib/dooping/utils";

// 圖表家族的共同底座：型別、色票取用、彙總工具、文字／鍵盤等價表。
//
// 這一組是「後台閱讀型」圖表（見文件〈Charts 圖表〉的邊界）：
// 零相依、資料點百位數以內、只有 hover 提示與 onSelect 鑽取。
// 縮放、刷選、圖內鑽取刻意不做——需要分析型互動請用成熟圖表庫。

/** 單序列資料點（BarChart／Pareto／TrendChart）。 */
export type BarDatum = { label: string; value: number; id?: string };
/** 堆疊分段（StackedBar）。顏色由宿主指定——序列色要跨期穩定，元件不猜。 */
export type Segment = { label: string; value: number; color: string };
/** 座標點（Scatter／LineChart）。 */
export type Point = { x: number; y: number; label?: string; id?: string };

/**
 * 分類色票。`PALETTE[n]` 只代表「這是哪一類」——類別身分，沒有好壞。
 * 值是 CSS 變數引用：換色票、切深淺模式都由 token 層決定，這裡永遠不需要動。
 * 順序即安全順序（相鄰取用永遠是近似最佳的 k 色子集），所以不要重排、不要循環。
 */
export const PALETTE = Array.from({ length: 8 }, (_, i) => `var(--chart-${i + 1})`);

/**
 * 類別數封頂：取值最大的 `max - 1` 名（維持原本相對順序），其餘彙總成「其他（N 項）」。
 *
 * 不循環取色的配套——第 9 類拿到跟第 1 類一樣的顏色，圖例會出現兩個同色不同名的項目。
 */
export function capItems(data: BarDatum[], max: number): BarDatum[] {
  if (data.length <= max) return data;
  const keep = new Set(
    [...data].sort((a, b) => b.value - a.value).slice(0, max - 1),
  );
  const kept = data.filter((d) => keep.has(d));
  const rest = data.filter((d) => !keep.has(d));
  return [
    ...kept,
    { label: `其他（${rest.length} 項）`, value: rest.reduce((s, d) => s + d.value, 0) },
  ];
}

export type ValueFmt = (n: number) => string;
export const defaultFmt: ValueFmt = (n) => formatNumber(n);

/**
 * 文字等價 ＋ 鍵盤等價，一張表兩個職責（見〈Charts 圖表〉的無障礙一節與
 * 無障礙四原則的「文字等價用表格」）：
 *
 * - **報讀器**：圖形掛 `role="img"` 後子樹被隱藏，精確數值由這張表補回
 *   （`<caption>` ＋ `scope`，報讀器有專門的表格瀏覽指令）。
 * - **鍵盤**：hover 提示與點擊鑽取對鍵盤使用者不可達——這張表兼任操作介面，
 *   有 `onSelect` 時每一列是一顆真按鈕。表平常 `sr-only`，**鍵盤焦點進入時現形**
 *   （同 skip-link 的慣例），明眼的鍵盤使用者才不會把焦點丟進看不見的地方。
 */
export function ChartDataTable({
  caption,
  head,
  rows,
  onSelect,
  selectedIndex,
  className,
}: {
  /** 表格標題＝這張圖在講什麼。報讀器靠它定位，所以必填。 */
  caption: string;
  head: string[];
  /** 每列＝[label, ...值們]（已格式化成字串）。 */
  rows: string[][];
  onSelect?: (index: number) => void;
  selectedIndex?: number;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "sr-only focus-within:not-sr-only focus-within:mt-2 focus-within:block",
        className,
      )}
    >
      <table className="w-full border-collapse rounded-md border text-xs">
        <caption className="p-1 text-left font-medium">{caption}</caption>
        <thead>
          <tr>
            {head.map((h) => (
              <th key={h} scope="col" className="border-b px-2 py-1 text-left font-medium">
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((cells, i) => (
            <tr key={i} className={cn(selectedIndex === i && "bg-muted")}>
              <th scope="row" className="px-2 py-1 text-left font-normal">
                {onSelect ? (
                  <button
                    type="button"
                    onClick={() => onSelect(i)}
                    aria-pressed={selectedIndex === i}
                    className="underline decoration-dotted underline-offset-2 outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {cells[0]}
                  </button>
                ) : (
                  cells[0]
                )}
              </th>
              {cells.slice(1).map((c, j) => (
                <td key={j} className="px-2 py-1 tabular-nums">
                  {c}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** 空資料的統一出口：一行「無資料」，不畫空白座標軸（見文件〈空資料、單點、全零〉）。 */
export function ChartEmpty({ children }: { children?: ReactNode }) {
  return (
    <p className="py-6 text-center text-sm text-muted-foreground">
      {children ?? "無資料"}
    </p>
  );
}

import { cn } from "@/lib/dooping/utils";
import { type ValueFmt, defaultFmt } from "@/components/dooping/base";

export interface BulletProps {
  /** 指標名稱。 */
  label: string;
  value: number;
  target: number;
  valueFmt?: ValueFmt;
  className?: string;
}

/**
 * 子彈圖：實際 vs 目標，一條就講完。放在卡片頂端當摘要。
 *
 * **這是唯一使用狀態色的圖**：超出目標走 `--danger`、未超出走 `--success`。
 * 預設假設「目標＝上限」（例如預算）；若你的指標是「目標＝下限」，
 * 請用文案講清楚，不要讓讀者自己猜紅色代表什麼。
 *
 * 無障礙：實際、目標、達成率都是**鄰近可見文字**，圖形部分 `aria-hidden`——
 * 不再附資料表，那會讓報讀器把同一份數字唸兩次。
 */
export function Bullet({ label, value, target, valueFmt = defaultFmt, className }: BulletProps) {
  const over = value > target;
  const max = Math.max(1, value, target);
  const pct = target > 0 ? Math.round((value / target) * 100) : null;
  const fill = over ? "hsl(var(--danger))" : "hsl(var(--success))";

  return (
    <div className={cn("space-y-1", className)}>
      <div className="flex items-baseline justify-between gap-2 text-xs">
        <span className="font-medium">{label}</span>
        <span className="tabular-nums">
          {valueFmt(value)} / 目標 {valueFmt(target)}
          {pct != null && <span className="ml-1 text-muted-foreground">（{pct}%）</span>}
        </span>
      </div>
      <div aria-hidden className="relative h-3 overflow-hidden rounded-sm bg-muted">
        <div className="h-full" style={{ width: `${(value / max) * 100}%`, backgroundColor: fill }} />
        {/* 目標刻度：一條清楚的直線，灰階列印下仍然讀得出「線在哪、條到沒到」 */}
        <div
          className="absolute inset-y-0 w-0.5 bg-foreground"
          style={{ left: `${(target / max) * 100}%` }}
        />
      </div>
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";
import { type ValueFmt, PALETTE, defaultFmt, ChartEmpty } from "@/components/dooping/base";

export interface HeatmapProps {
  rowLabels: string[];
  colLabels: string[];
  /** 列 × 欄。**`null` 代表無資料，不是 0**——沒有發生和數值為零是兩件事。 */
  cells: (number | null)[][];
  title?: string;
  /**
   * 色階值域。不給就依當期資料自動取 min/max。
   * **跨期比較時務必手動指定**：多張並排的熱圖各自用自動值域，
   * 每張的「最深」代表不同的數字，並排比較就是錯的——而且錯得看不出來。
   */
  domain?: [number, number];
  fmt?: ValueFmt;
  /** 色階圖例（預設開）。 */
  legend?: boolean;
  onSelect?: (row: number, col: number, value: number | null) => void;
  className?: string;
}

/**
 * 熱圖：兩個維度交叉之後，值集中在哪裡。格子數 100 以內——
 * 人沒辦法在 2500 格裡找出模式，那需要排序後的清單或 Pareto。
 *
 * 無障礙：熱圖**本來就是真表格**——數值是可見文字、顏色只是輔助。
 * 不另附 sr-only 表格，把表格語意補正即可（caption／scope／列標頭）。
 */
export function Heatmap({
  rowLabels,
  colLabels,
  cells,
  title = "熱圖",
  domain,
  fmt = defaultFmt,
  legend = true,
  onSelect,
  className,
}: HeatmapProps) {
  const flat = cells.flat().filter((v): v is number => v != null);
  if (rowLabels.length === 0 || flat.length === 0) return <ChartEmpty />;

  let [lo, hi] = domain ?? [Math.min(...flat), Math.max(...flat)];
  // 值全部相同時把值域撐開，避免整張同色——若「全部一樣」在業務上有意義，用文字說明
  if (lo === hi) [lo, hi] = [lo - 1, hi + 1];

  // 染色量壓在 8%–78%：上限保住深色格上的文字對比，下限讓最小值仍看得出「有值」
  const tint = (v: number) => 8 + ((v - lo) / (hi - lo)) * 70;

  return (
    <div className={cn("overflow-x-auto", className)}>
      <table className="border-collapse text-xs">
        <caption className="p-1 text-left font-medium">{title}</caption>
        <thead>
          <tr>
            <td />
            {colLabels.map((c) => (
              <th key={c} scope="col" className="px-2 py-1 text-center font-medium">
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rowLabels.map((r, ri) => (
            <tr key={r}>
              <th scope="row" className="pr-2 text-left font-medium">
                {r}
              </th>
              {colLabels.map((_, ci) => {
                const v = cells[ri]?.[ci] ?? null;
                return (
                  <td
                    key={ci}
                    onClick={onSelect ? () => onSelect(ri, ci, v) : undefined}
                    className={cn(
                      "min-w-14 border border-background px-2 py-1.5 text-center tabular-nums",
                      onSelect && "cursor-pointer",
                      v == null && "bg-muted text-muted-foreground",
                    )}
                    style={
                      v == null
                        ? undefined
                        : { backgroundColor: `color-mix(in srgb, ${PALETTE[0]} ${tint(v)}%, transparent)` }
                    }
                  >
                    {v == null ? "—" : fmt(v)}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
      {legend && (
        <p className="mt-1 flex items-center gap-2 text-xs text-muted-foreground">
          <span
            aria-hidden
            className="inline-block h-2.5 w-16 rounded-sm"
            style={{
              background: `linear-gradient(to right, color-mix(in srgb, ${PALETTE[0]} 8%, transparent), color-mix(in srgb, ${PALETTE[0]} 78%, transparent))`,
            }}
          />
          淺 {fmt(lo)} → 深 {fmt(hi)}；灰＝無資料
        </p>
      )}
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";

export interface LegendItem {
  label: string;
  color: string;
}

/**
 * 圖例：色塊 ＋ 文字標籤。**色塊永遠不會單獨出現**——只有色塊的圖例，
 * 灰階列印後全部一樣。
 *
 * 只有多序列的圖（StackedBar）需要圖例；單序列的圖不要放——
 * 一個顏色配一行說明只是佔位子，標題已經說完了。
 */
export function Legend({ items, className }: { items: LegendItem[]; className?: string }) {
  return (
    <ul className={cn("flex flex-wrap items-center gap-x-4 gap-y-1 text-xs", className)}>
      {items.map((it) => (
        <li key={it.label} className="flex items-center gap-1.5">
          <span
            aria-hidden
            className="inline-block size-2.5 rounded-sm border border-foreground/20"
            style={{ backgroundColor: it.color }}
          />
          {it.label}
        </li>
      ))}
    </ul>
  );
}

import { type Point, PALETTE, ChartDataTable, ChartEmpty } from "@/components/dooping/base";

export interface LineChartProps {
  /** 累積分布曲線的點，**x 與 y 都必須先正規化到 0–1**。 */
  points: Point[];
  title?: string;
  /** 對角基準線（完全平均分布），預設開。曲線離對角線越遠＝越集中。 */
  diagonal?: boolean;
  height?: number;
  className?: string;
}

/**
 * 累積分布折線：配對角基準線看「離平均分布差多遠」。
 * 例：前 20% 的對象貢獻了多少總量。
 *
 * 對角線是這張圖的全部意義所在——沒有基準線，這條曲線讀不出任何東西。
 * 時間序列不要用這支（那是 TrendChart）：這裡兩軸都是 0–1 的比例，語意不同。
 */
export function LineChart({
  points,
  title = "累積分布",
  diagonal = true,
  height = 220,
  className,
}: LineChartProps) {
  if (points.length === 0) return <ChartEmpty />;

  const W = 240;
  const pad = 12;
  const X = (x: number) => pad + x * (W - pad * 2);
  const Y = (y: number) => pad + (1 - y) * (height - pad * 2);
  const sorted = [...points].sort((a, b) => a.x - b.x);
  // 摘要取最接近 x=0.2 的點：「前 20% 佔多少」是這張圖被畫出來的原因
  const at20 = sorted.reduce((a, b) => (Math.abs(b.x - 0.2) < Math.abs(a.x - 0.2) ? b : a), sorted[0]);

  return (
    <div className={className}>
      <svg
        role="img"
        aria-label={`${title}，前 ${Math.round(at20.x * 100)}% 累積約 ${Math.round(at20.y * 100)}%`}
        viewBox={`0 0 ${W} ${height}`}
        className="block w-full"
        style={{ maxWidth: W }}
      >
        <line x1={pad} y1={height - pad} x2={W - pad} y2={height - pad} stroke="var(--chart-axis)" />
        <line x1={pad} y1={pad} x2={pad} y2={height - pad} stroke="var(--chart-axis)" />
        {diagonal && (
          <line
            x1={X(0)}
            y1={Y(0)}
            x2={X(1)}
            y2={Y(1)}
            stroke="var(--chart-grid)"
            strokeDasharray="4 3"
          />
        )}
        <polyline
          points={[`${X(0)},${Y(0)}`, ...sorted.map((p) => `${X(p.x)},${Y(p.y)}`)].join(" ")}
          fill="none"
          stroke={PALETTE[0]}
          strokeWidth={2}
        />
      </svg>
      <ChartDataTable
        caption={`${title}（累積比例）`}
        head={["位置", "累積"]}
        rows={sorted.map((p) => [
          p.label ?? `前 ${Math.round(p.x * 100)}%`,
          `${Math.round(p.y * 100)}%`,
        ])}
      />
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";
import {
  type BarDatum,
  type ValueFmt,
  PALETTE,
  capItems,
  defaultFmt,
  ChartDataTable,
  ChartEmpty,
} from "@/components/dooping/base";

export interface ParetoProps {
  /** 元件內部自行由大到小排序，宿主不必先排。 */
  data: BarDatum[];
  title?: string;
  maxItems?: number;
  valueFmt?: ValueFmt;
  onSelect?: (index: number, datum: BarDatum) => void;
  selectedIndex?: number;
  height?: number;
  className?: string;
}

/**
 * 柏拉圖：長條由大到小 ＋ 累積百分比折線。回答「前幾項就佔掉多少」。
 *
 * 累積線是本組唯一的「雙軸」——它是柏拉圖的定義，不是為了省一張圖疊上去的。
 * 即使如此也不畫第二條 Y 軸刻度，累積值只在提示與資料表裡以百分比呈現。
 *
 * 單一顏色是刻意的例外：整張圖的語意就是排序，分類配色反而添亂。
 */
export function Pareto({
  data,
  title = "柏拉圖",
  maxItems = 12,
  valueFmt = defaultFmt,
  onSelect,
  selectedIndex,
  height = 180,
  className,
}: ParetoProps) {
  if (data.length === 0) return <ChartEmpty />;
  const sorted = capItems([...data].sort((a, b) => b.value - a.value), maxItems);
  const total = Math.max(1, sorted.reduce((s, d) => s + d.value, 0));
  const max = Math.max(1, ...sorted.map((d) => d.value));

  const slot = 56;
  const pad = { top: 10, bottom: 20 };
  const plotH = height - pad.top - pad.bottom;
  const W = sorted.length * slot;

  let acc = 0;
  const cum = sorted.map((d) => (acc += d.value) / total);
  const lineX = (i: number) => i * slot + 10 + (slot - 20) / 2;
  const lineY = (c: number) => pad.top + (1 - c) * plotH;
  const cutoff = cum.findIndex((c) => c >= 0.8);

  return (
    <div className={cn("overflow-x-auto", className)}>
      <svg
        role="img"
        aria-label={`${title}，共 ${sorted.length} 項，前 ${cutoff + 1} 項累積佔 ${Math.round(cum[Math.max(cutoff, 0)] * 100)}%`}
        viewBox={`0 0 ${W} ${height}`}
        width={W}
        height={height}
        className="block"
      >
        <line x1={0} y1={height - pad.bottom} x2={W} y2={height - pad.bottom} stroke="var(--chart-axis)" />
        {sorted.map((d, i) => {
          const h = (d.value / max) * plotH;
          const x = i * slot + 10;
          const dim = selectedIndex != null && selectedIndex !== i;
          return (
            <g
              key={d.id ?? d.label}
              onClick={onSelect ? () => onSelect(i, d) : undefined}
              className={cn(onSelect && "cursor-pointer")}
            >
              <title>{`${d.label}：${valueFmt(d.value)}（累積 ${Math.round(cum[i] * 100)}%）`}</title>
              <rect
                x={x}
                y={height - pad.bottom - h}
                width={slot - 20}
                height={h}
                fill={PALETTE[0]}
                opacity={dim ? 0.35 : 1}
              />
              <text x={x + (slot - 20) / 2} y={height - 6} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
                {d.label}
              </text>
            </g>
          );
        })}
        <polyline
          points={cum.map((c, i) => `${lineX(i)},${lineY(c)}`).join(" ")}
          fill="none"
          stroke="var(--chart-text)"
          strokeWidth={1.5}
        />
        {cum.map((c, i) => (
          <circle key={i} cx={lineX(i)} cy={lineY(c)} r={2.5} fill="var(--chart-text)" />
        ))}
      </svg>
      <ChartDataTable
        caption={`${title}（資料表，含累積佔比）`}
        head={["項目", "數值", "累積"]}
        rows={sorted.map((d, i) => [d.label, valueFmt(d.value), `${Math.round(cum[i] * 100)}%`])}
        onSelect={onSelect ? (i) => onSelect(i, sorted[i]) : undefined}
        selectedIndex={selectedIndex}
      />
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";
import {
  type Point,
  type ValueFmt,
  PALETTE,
  defaultFmt,
  ChartDataTable,
  ChartEmpty,
} from "@/components/dooping/base";

export interface ScatterProps {
  points: Point[];
  title?: string;
  /** 兩軸各是什麼。不標的話整張圖無從得知——視同必填。 */
  xLabel: string;
  yLabel: string;
  valueFmt?: ValueFmt;
  onSelect?: (index: number, point: Point) => void;
  selectedIndex?: number;
  color?: string;
  height?: number;
  className?: string;
}

/**
 * 散布圖：兩個數值之間有沒有關係。點數 20–300 才有意義——
 * 少於 10 個點看不出關係卻容易讓人腦補出一條線，上千個點請先在資料層彙總。
 *
 * 軸範圍取自資料的 min/max（**不從 0 起算**）：散布圖看的是分散形狀，不是絕對大小。
 */
export function Scatter({
  points,
  title = "散布圖",
  xLabel,
  yLabel,
  valueFmt = defaultFmt,
  onSelect,
  selectedIndex,
  color = PALETTE[0],
  height = 220,
  className,
}: ScatterProps) {
  if (points.length === 0) return <ChartEmpty />;

  const W = 320;
  const pad = { top: 10, right: 10, bottom: 28, left: 10 };
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const [x0, x1] = [Math.min(...xs), Math.max(...xs)];
  const [y0, y1] = [Math.min(...ys), Math.max(...ys)];
  const X = (x: number) => pad.left + ((x - x0) / Math.max(1e-9, x1 - x0)) * (W - pad.left - pad.right);
  const Y = (y: number) => pad.top + (1 - (y - y0) / Math.max(1e-9, y1 - y0)) * (height - pad.top - pad.bottom);

  return (
    <div className={className}>
      <svg
        role="img"
        aria-label={`${title}，${points.length} 個點，橫軸 ${xLabel}、縱軸 ${yLabel}`}
        viewBox={`0 0 ${W} ${height}`}
        className="block w-full"
        style={{ maxWidth: W }}
      >
        <line x1={pad.left} y1={height - pad.bottom} x2={W - pad.right} y2={height - pad.bottom} stroke="var(--chart-axis)" />
        <line x1={pad.left} y1={pad.top} x2={pad.left} y2={height - pad.bottom} stroke="var(--chart-axis)" />
        {points.map((p, i) => {
          const dim = selectedIndex != null && selectedIndex !== i;
          return (
            <circle
              key={p.id ?? i}
              cx={X(p.x)}
              cy={Y(p.y)}
              r={selectedIndex === i ? 5.5 : 4}
              fill={color}
              opacity={dim ? 0.3 : 0.8}
              onClick={onSelect ? () => onSelect(i, p) : undefined}
              className={cn(onSelect && "cursor-pointer")}
            >
              <title>{`${p.label ?? `第 ${i + 1} 點`}：${xLabel} ${valueFmt(p.x)}、${yLabel} ${valueFmt(p.y)}`}</title>
            </circle>
          );
        })}
        <text x={(W + pad.left) / 2} y={height - 8} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
          {xLabel} →
        </text>
        <text
          x={pad.left + 4}
          y={pad.top + 2}
          fontSize={10}
          fill="var(--chart-text)"
        >
          ↑ {yLabel}
        </text>
      </svg>
      <ChartDataTable
        caption={`${title}（各點座標）`}
        head={["點", xLabel, yLabel]}
        rows={points.map((p, i) => [p.label ?? `第 ${i + 1} 點`, valueFmt(p.x), valueFmt(p.y)])}
        onSelect={onSelect ? (i) => onSelect(i, points[i]) : undefined}
        selectedIndex={selectedIndex}
      />
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";
import { type Segment, type ValueFmt, defaultFmt, ChartDataTable, ChartEmpty } from "@/components/dooping/base";

export interface StackedBarRow {
  label: string;
  segments: Segment[];
}

export interface StackedBarProps {
  rows: StackedBarRow[];
  title?: string;
  valueFmt?: ValueFmt;
  onSelectRow?: (index: number, row: StackedBarRow) => void;
  selectedRow?: number;
  /** 單列高度（px）。 */
  height?: number;
  className?: string;
}

/**
 * 水平堆疊長條：看一個總量由哪些部分構成，同時比較多個總量。
 *
 * 每列右側**固定顯示總量**——堆疊圖最常被問的就是「所以總共多少」，
 * 人沒辦法用眼睛把幾個色塊加起來。
 *
 * 分段顏色由宿主指定（`Segment.color`）：序列色要**跨期穩定**、跟實體走，
 * 元件沒有那個知識，猜了只會猜錯。
 *
 * 無障礙：數值已在鄰近可見文字（列標籤＋合計），圖形部分 `aria-hidden`，
 * 分段明細由資料表提供——避免同一份資料被報讀器唸兩次。
 */
export function StackedBar({
  rows,
  title = "堆疊長條",
  valueFmt = defaultFmt,
  onSelectRow,
  selectedRow,
  height = 22,
  className,
}: StackedBarProps) {
  if (rows.length === 0) return <ChartEmpty />;
  const totals = rows.map((r) => r.segments.reduce((s, x) => s + x.value, 0));
  const max = Math.max(1, ...totals);
  const segNames = [...new Set(rows.flatMap((r) => r.segments.map((s) => s.label)))];

  return (
    <div className={className}>
      <div className="space-y-1.5">
        {rows.map((r, i) => {
          const dim = selectedRow != null && selectedRow !== i;
          return (
            <div
              key={r.label}
              className={cn("flex items-center gap-2", onSelectRow && "cursor-pointer", dim && "opacity-50")}
              onClick={onSelectRow ? () => onSelectRow(i, r) : undefined}
            >
              <span className="w-24 shrink-0 truncate text-xs">{r.label}</span>
              <div aria-hidden className="flex h-full flex-1 overflow-hidden rounded-sm" style={{ height }}>
                {r.segments.map((s) => (
                  <div
                    key={s.label}
                    title={`${s.label}：${valueFmt(s.value)}`}
                    style={{ width: `${(s.value / max) * 100}%`, backgroundColor: s.color }}
                  />
                ))}
              </div>
              <span className="w-20 shrink-0 text-right text-xs tabular-nums">{valueFmt(totals[i])}</span>
            </div>
          );
        })}
      </div>
      <ChartDataTable
        caption={`${title}（各列分段明細）`}
        head={["項目", ...segNames, "合計"]}
        rows={rows.map((r, i) => [
          r.label,
          ...segNames.map((n) => {
            const seg = r.segments.find((s) => s.label === n);
            return seg ? valueFmt(seg.value) : "—";
          }),
          valueFmt(totals[i]),
        ])}
        onSelect={onSelectRow ? (i) => onSelectRow(i, rows[i]) : undefined}
        selectedIndex={selectedRow}
      />
    </div>
  );
}

import { cn } from "@/lib/dooping/utils";
import {
  type BarDatum,
  type ValueFmt,
  PALETTE,
  defaultFmt,
  ChartDataTable,
  ChartEmpty,
} from "@/components/dooping/base";

export interface TrendChartProps {
  /** `label` 當 x 軸刻度——x 軸必須是**等距的時間**（每月、每週）。 */
  data: BarDatum[];
  title?: string;
  /**
   * Y 軸是否從 0 起算，預設 **true**。
   * 金額、數量這類絕對量一律從 0 起算——才不會把 2% 的波動畫成懸崖。
   * 只有看「相對變化」時才關；關掉時兩端數值仍會標示，那是誠實的底線。
   */
  zeroBased?: boolean;
  valueFmt?: ValueFmt;
  onSelect?: (index: number, datum: BarDatum) => void;
  selectedIndex?: number;
  color?: string;
  height?: number;
  className?: string;
}

/**
 * 趨勢折線：同一個量隨時間怎麼變。
 * 單一資料點沒有趨勢可言——只畫該點並置中，不畫線。
 */
export function TrendChart({
  data,
  title = "趨勢折線",
  zeroBased = true,
  valueFmt = defaultFmt,
  onSelect,
  selectedIndex,
  color = PALETTE[0],
  height = 180,
  className,
}: TrendChartProps) {
  if (data.length === 0) return <ChartEmpty />;

  const slot = 64;
  const pad = { top: 18, bottom: 20 };
  const plotH = height - pad.top - pad.bottom;
  const W = Math.max(1, data.length) * slot;

  const lo = zeroBased ? 0 : Math.min(...data.map((d) => d.value));
  const hi = Math.max(zeroBased ? 1 : lo + 1, ...data.map((d) => d.value));
  const X = (i: number) => i * slot + slot / 2;
  const Y = (v: number) => pad.top + (1 - (v - lo) / (hi - lo)) * plotH;

  const first = data[0];
  const last = data[data.length - 1];

  return (
    <div className={cn("overflow-x-auto", className)}>
      <svg
        role="img"
        aria-label={`${title}，${data.length} 期，${first.label} ${valueFmt(first.value)} 到 ${last.label} ${valueFmt(last.value)}`}
        viewBox={`0 0 ${W} ${height}`}
        width={W}
        height={height}
        className="block"
      >
        <line x1={0} y1={height - pad.bottom} x2={W} y2={height - pad.bottom} stroke="var(--chart-axis)" />
        {data.length > 1 && (
          <polyline
            points={data.map((d, i) => `${X(i)},${Y(d.value)}`).join(" ")}
            fill="none"
            stroke={color}
            strokeWidth={2}
          />
        )}
        {data.map((d, i) => {
          const sel = selectedIndex === i;
          // 端點值永遠標示：zeroBased 關掉時它是誠實的底線，開著時也是最常被問的兩個數字
          const endpoint = i === 0 || i === data.length - 1;
          return (
            <g
              key={d.id ?? d.label}
              onClick={onSelect ? () => onSelect(i, d) : undefined}
              className={cn(onSelect && "cursor-pointer")}
            >
              <title>{`${d.label}：${valueFmt(d.value)}`}</title>
              <circle cx={X(i)} cy={Y(d.value)} r={sel ? 5 : 3.5} fill={color} />
              {endpoint && (
                <text x={X(i)} y={Y(d.value) - 8} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
                  {valueFmt(d.value)}
                </text>
              )}
              <text x={X(i)} y={height - 6} textAnchor="middle" fontSize={10} fill="var(--chart-text)">
                {d.label}
              </text>
            </g>
          );
        })}
      </svg>
      <ChartDataTable
        caption={`${title}（各期數值）`}
        head={["期別標籤", "數值"]}
        rows={data.map((d) => [d.label, valueFmt(d.value)])}
        onSelect={onSelect ? (i) => onSelect(i, data[i]) : undefined}
        selectedIndex={selectedIndex}
      />
    </div>
  );
}
